import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Build the backdrop gradient plane
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const gradientCanvas = document.createElement('canvas');
  gradientCanvas.width = 512;
  gradientCanvas.height = 512;
  const gradCtx = gradientCanvas.getContext('2d');

  // Vertical gradient: surface (#0b0b10) at top to ink (#16161d) at bottom
  const grad = gradCtx.createLinearGradient(0, 0, 0, 512);
  grad.addColorStop(0, '#0b0b10');
  grad.addColorStop(1, '#16161d');
  gradCtx.fillStyle = grad;
  gradCtx.fillRect(0, 0, 512, 512);

  // Add subtle grain
  const imgData = gradCtx.getImageData(0, 0, 512, 512);
  const data = imgData.data;
  for (let i = 0; i < data.length; i += 4) {
    const grain = (Math.random() - 0.5) * 8;
    data[i] += grain;
    data[i + 1] += grain;
    data[i + 2] += grain;
  }
  gradCtx.putImageData(imgData, 0, 0);

  const backdropTex = new THREE.CanvasTexture(gradientCanvas);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = uv().mul(color(0xffffff));
  backdropMat.map = backdropTex;
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;

  // Main hero subhead plane with image
  const planeGeom = new THREE.PlaneGeometry(4, 2.5);
  const planeMat = new MeshBasicNodeMaterial();

  const container = new THREE.Group();
  container.position.copy(new THREE.Vector3(config.scenePosition?.x ?? 0, config.scenePosition?.y ?? 1.85, config.scenePosition?.z ?? 0));

  // Load and apply the image texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    planeMat.map = tex;
    planeMat.needsUpdate = true;
  });

  const plane = new THREE.Mesh(planeGeom, planeMat);
  plane.position.z = 0;

  // Create text from config
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textGroup = null;

  if (textItems.length > 0) {
    textGroup = new THREE.Group();
    let yOffset = 0.8;

    for (const item of textItems) {
      const fontSize = item.typography?.fontSize ?? 42;
      const textContent = String(item.text || '');
      const textColor = item.typography?.color || '#e8ecf2';

      const textMesh = ctx.fontAtlas.createText(textContent, {
        fontSize,
        color: textColor,
        align: 'center',
        maxWidthPx: 500,
        letterSpacingPx: item.typography?.letterSpacing ?? 0,
      });

      textMesh.position.y = yOffset;
      textMesh.position.z = 0.1;
      textGroup.add(textMesh);
      yOffset -= 0.5;
    }

    container.add(textGroup);
  }

  container.add(backdrop);
  container.add(plane);

  // Cleanup handler
  container.userData.cleanup = () => {
    backdropGeom.dispose();
    planeGeom.dispose();
    backdropMat.dispose();
    planeMat.dispose();
    if (backdropTex) backdropTex.dispose();
  };

  return container;
}
